"""Same-year comparisons, with distinct descriptions and no invented causal links."""
import json
from pathlib import Path
rows=[]
def add(year,eraId,rt,rd,wt,wd,connection,lessonIds,sources):
 rows.append(dict(id=f'world-{year}',year=year,eraId=eraId,russia=dict(title=rt,description=rd),world=dict(title=wt,description=wd),connection=connection,lessonIds=lessonIds.split(),sources=sources.split()))
add(1054,'era-02','Смерть Ярослава Мудрого',
'После смерти киевского князя главные столы занимали его сыновья. Сохранение единства зависело от их соглашений, порядка старшинства и отношений с другими ветвями династии. Дальнейшие конфликты не были простым автоматическим исполнением одного завещания.',
'Конфликт Рима и Константинополя',
'Папские посланники и патриарх Михаил Керуларий обменялись церковными осуждениями. 1054 год принято связывать с расколом между западным и восточным христианством, но разделение складывалось долго и не было мгновенно осознано всеми верующими как окончательное.',
'Русь входила в христианский мир через византийскую церковную традицию. Совпадение помогает увидеть общий религиозный контекст, но смерть князя не была причиной церковного конфликта.','02-010 02-014 02-018','ar-yaroslav ar-pvl-full ref-schism1054')
add(1097,'era-02','Любечский съезд князей',
'Князья договаривались прекратить взаимную борьбу и закрепить владения отдельных ветвей династии. Формула «каждый да держит отчину свою» не отменила последующих конфликтов: уже вскоре последовали новые насильственные действия между князьями.',
'Первый крестовый поход: Никея',
'В мае–июне войска Первого крестового похода осаждали Никею. Город перешёл под власть византийского императора после соглашения с его представителями. Сотрудничество латинских воинов и Византии сочеталось с недоверием и различием политических целей.',
'Оба сюжета показывают, что союзники не становились единой властью и зависели от соглашений. Это сравнение политических механизмов, а не утверждение прямого влияния крестоносцев на решения Любечского съезда.','02-014 02-022','ar-lyubech ar-pvl-full ref-nicaea1097')
add(1242,'era-03','Битва на Чудском озере',
'Войска Александра Ярославича и его союзников нанесли поражение силам Ливонского ордена и их союзникам. Сражение рассматривают в рамках борьбы за влияние на востоке Прибалтики; позднейшая память заметно расширила его символическое значение.',
'Отход монгольских сил из Венгрии',
'После вторжения 1241 года монгольские войска в 1242 году оставили Венгрию. Исследователи обсуждают военные, политические, хозяйственные и природные обстоятельства этого решения. Один объясняющий фактор не следует представлять окончательно доказанной единственной причиной.',
'Военное давление в Европе исходило от разных сил. Победа на Чудском озере не завершила ордынскую зависимость русских земель и не была причиной отхода монголов из Венгрии.','03-007 03-010 03-011 03-012','ref-nevsky med-novgorod med-mongol-expansion ref-hungary1242')
add(1453,'era-04','Завершение длительной московской усобицы',
'Смерть Дмитрия Шемяки в Новгороде в 1453 году стала заключительным событием многолетней борьбы за московский великокняжеский стол. Василий II вернулся к власти раньше, но противостояние продолжалось. Укрепление его линии сопровождалось жестокими действиями обеих сторон.',
'Взятие Константинополя',
'29 мая войска османского султана Мехмеда II захватили столицу Византии. Византийская империя прекратила существование, хотя её культурные и церковные традиции продолжали жить. Город стал столицей Османской державы.',
'На Руси сохранялись церковные связи с византийской традицией, но падение Константинополя не превратило Москву мгновенно в её политическую наследницу. Идеи особого места Москвы формировались позже и требуют отдельных источников.','04-005 04-013 04-014','ref-moscow-civilwar ref-constantinople fei-autokephaly')
add(1492,'era-04','Основание Ивангородской крепости',
'По распоряжению Ивана III на реке Нарове построили крепость напротив Нарвы. Новый укреплённый пункт усиливал военное и торговое присутствие Москвы у балтийских путей. Это не означало немедленного получения контроля над всей Балтикой.',
'Первое плавание Колумба через Атлантику',
'Экспедиция Христофора Колумба достигла островов Карибского моря. Для народов Америки это не было началом их истории: там уже существовали разнообразные общества. Плавание открыло длительный этап европейской экспансии, насилия и обменов между континентами.',
'Ивангород и атлантическая экспедиция показывают разные масштабы поиска торговых возможностей и государственной силы. Совпадение по году не доказывает, что строительство русской крепости было вызвано плаванием Колумба.','04-006 04-009','ref-ivangorod med-growth ref-columbus')
add(1547,'era-05','Венчание Ивана IV на царство',
'Иван IV принял царский титул и был венчан в московском Успенском соборе. Титул усиливал притязания правителя на особый статус. В том же году пожар и волнения в Москве показали уязвимость власти перед городским кризисом.',
'Начало правления Эдуарда VI в Англии',
'После смерти Генриха VIII в январе престол получил его несовершеннолетний сын Эдуард VI, коронованный в феврале. Управление находилось в руках взрослых советников, а религиозные преобразования продолжались в условиях борьбы придворных групп.',
'Церемонии и наследование укрепляли монархическую законность в разных странах, но реальные полномочия, религиозные институты и отношения с элитами различались. Одинаковый год коронаций не означает одинаковый государственный строй.','05-001 05-003','muscovy med-cambridge-chronology ref-edward1547')
add(1649,'era-05','Соборное уложение',
'В Московском государстве приняли обширный свод законов. Он регулировал суд, службу и положение разных групп населения, закрепил бессрочный сыск беглых крестьян. Упорядочение права сочеталось с усилением личной зависимости и защиты государевой власти.',
'Казнь Карла I и английская республика',
'После гражданских войн король Карл I был осуждён и 30 января казнён. Монархию и палату лордов упразднили, Англию объявили республикой. Это не означало установления всеобщего политического равенства; влияние армии и борьба за власть сохранялись.',
'В одном году произошли разные способы перестройки власти: укрепление московской монархии и устранение английского короля. Такое сопоставление помогает избегать идеи единой обязательной для всех стран последовательности развития.','05-017 05-018 05-019','em-code1649 em-law1649 ref-charles1649')
add(1755,'era-06','Основание Московского университета',
'По указу Елизаветы Петровны был учреждён Московский университет, подготовленный при участии Ивана Шувалова и Михаила Ломоносова. Он стал новым центром преподавания и научной работы. Возможности поступления и последующей карьеры оставались связаны с устройством сословного общества.',
'Лиссабонское землетрясение',
'1 ноября землетрясение, цунами и пожары разрушили значительную часть Лиссабона. Катастрофа побудила власти собирать сведения о последствиях и перестраивать город. В Европе она стала предметом споров о природе, религии и объяснении человеческих бедствий.',
'Оба сюжета относятся к эпохе расширения научных знаний, но университет не был следствием катастрофы: российский указ был издан раньше. Сравнение показывает разные задачи науки и управления в одном историческом времени.','06-015 06-022 06-027','root-university ref-lomonosov ref-lisbon1755')
add(1789,'era-06','Победа при Рымнике',
'В ходе русско-турецкой войны русско-австрийские войска под командованием Суворова и принца Кобургского разгромили османские силы при Рымнике. Россия расширяла влияние в Северном Причерноморье, действуя в системе союзов и соперничества европейских монархий.',
'Начало Французской революции',
'Созыв Генеральных штатов, провозглашение Национального собрания и взятие Бастилии 14 июля обозначили революционный кризис французской монархии. Были поставлены вопросы о представительстве, правах и источнике государственной власти; дальнейшее развитие не было заранее определено.',
'Российская внешняя политика ещё строилась вокруг династических войн, а во Франции менялось понимание законной власти. В последующие годы революция повлияла на европейскую дипломатию и отношение Екатерины II к несогласию внутри империи.','06-017 06-018 06-021','ref-suvorov ref-catherine ref-france1789')
add(1812,'era-07','Вторжение Наполеона в Россию',
'Великая армия вторглась в Российскую империю. После Бородинского сражения русская армия оставила Москву, но занятие города не привело к миру. Отступление наполеоновских войск стало катастрофой из-за сочетания боёв, истощения снабжения, болезней и погоды.',
'Война США и Великобритании',
'Соединённые Штаты объявили войну Великобритании. Морские ограничения и принудительный набор моряков сочетались с конфликтами в Северной Америке. Боевые действия шли на границе с британскими колониями, на озёрах и на море; эта война продолжалась после окончания кампании в России.',
'Британия одновременно участвовала в борьбе с Наполеоном и воевала с США. Общий международный контекст связывает эти войны, но американская война 1812 года и российская Отечественная война — разные конфликты.','07-003 07-004 07-006','napoleonic ir-campaign ref-war1812')
add(1861,'era-07','Отмена крепостного права',
'Александр II утвердил освобождение помещичьих крестьян. Они получили личную свободу, но наделы, повинности, выкуп и общинные ограничения определяли условия перехода. Реформа открывала новые возможности и одновременно сохраняла тяжёлые хозяйственные конфликты.',
'Начало Гражданской войны в США',
'В апреле нападение на форт Самтер обозначило начало большой войны между федеральной властью и отделившимися южными штатами. Центральное место в конфликте занимало рабство, но его общенациональная юридическая отмена произошла в 1865 году, а не в день первого сражения.',
'Освобождение зависимых людей происходило в разных правовых и военных условиях. Российское крепостничество и американское расовое рабство имели общие черты принуждения, но существенно различались; их нельзя считать тождественными институтами.','07-013 07-014 07-015','reforms agrarian ref-sumter1861')
add(1917,'era-08','Российские революции',
'В феврале по старому стилю падение монархии привело к Временному правительству и новой роли Советов. В октябре большевики и их союзники свергли правительство. Война, земельный вопрос и спор о власти влияли на оба кризиса; выход из мировой войны последовал в 1918 году.',
'Вступление США в Первую мировую войну',
'В апреле США объявили войну Германии после возобновления неограниченной подводной войны и обострения дипломатического конфликта. Американское участие усиливало противников Германии, но развёртывание армии и снабжения потребовало времени.',
'Пока российское общество требовало решения вопроса о мире, другая крупная держава вступала в ту же войну. Это помогает понять международные ограничения решений Временного правительства и большевиков, не сводя революцию к зарубежному воздействию.','08-009 08-010 08-012 08-015 08-027','revolution virginia ohio ref-us1917')
add(1945,'era-09','Победа над нацистской Германией и война с Японией',
'Советские войска участвовали в разгроме Германии; в мае война в Европе завершилась капитуляцией нацистского государства. В августе СССР вступил в войну против Японии. Победа сопровождалась огромными людскими потерями и необходимостью восстанавливать разорённые территории.',
'Учреждение Организации Объединённых Наций',
'Устав ООН подписали 26 июня в Сан-Франциско; он вступил в силу 24 октября. Организацию создавали для поддержания мира и сотрудничества после мировой войны. СССР стал одним из постоянных членов Совета Безопасности с правом вето.',
'Военный союз способствовал созданию новой международной организации, но общие учреждения не устранили разногласий победителей. Завершение войны в Европе в мае нельзя смешивать с окончанием всей Второй мировой войны в сентябре.','09-019 09-020 09-021 09-022 09-024','sov-eastfront warstudy sov-reconstruction ref-un1945')
add(1961,'era-09','Полёт Юрия Гагарина',
'12 апреля корабль «Восток-1» с Юрием Гагариным совершил первый пилотируемый орбитальный полёт. Достижение стало результатом работы большой научно-технической системы и личного риска космонавта. Оно имело международное политическое значение в соревновании сверхдержав.',
'Строительство Берлинской стены',
'13 августа власти ГДР закрыли границу между восточными и западными секторами Берлина, затем возводили постоянные заграждения. Стена ограничила возможность жителей покидать ГДР и стала символом разделения Европы. Пограничный режим сохранялся до 1989 года.',
'Техническое достижение и закрытая граница существовали в одном мире холодной войны. Они показывают разные стороны соперничества систем; полёт Гагарина не был причиной возведения стены.','09-024 09-026 09-029','ref-gagarin sov-space ref-berlin1961')
add(1991,'era-09','Прекращение существования СССР',
'После августовского путча и усиления самостоятельности республик декабрьские соглашения и решения союзных органов завершили распад СССР. Российская Федерация продолжила существование как самостоятельное государство. Экономические и политические последствия перехода не завершились в момент юридических решений.',
'Война в Персидском заливе',
'В январе–феврале международная коалиция во главе с США провела боевую операцию против Ирака после его вторжения в Кувейт в 1990 году. Иракские войска были вытеснены из Кувейта; последующие санкции и конфликты продолжались. Это другая война, чем вторжение в Ирак в 2003 году.',
'СССР ещё участвовал в международной дипломатии, когда его собственное государственное устройство распадалось. Сопоставление показывает изменение мировой роли СССР и США, но война за Кувейт не является достаточным объяснением распада Союза.','09-035 09-040 09-041 09-059 10-001','collapse gorbachev ref-gulf1991')
p=Path('src/content/world-context.json')
